async function duration(f:File){return new Promise<number>((yes,no)=>{const v=document.createElement('video'),u=URL.createObjectURL(f);const finish=(value?:number)=>{clearTimeout(timer);URL.revokeObjectURL(u);v.removeAttribute('src');value?yes(value):no(Error('Cannot read this video. Try MP4 (H.264) or WebM.'))};const timer=setTimeout(()=>finish(),15000);v.preload='metadata';v.onloadedmetadata=()=>finish(Number.isFinite(v.duration)&&v.duration>0?v.duration:undefined);v.onerror=()=>finish();v.src=u})}
