async function upload(f:File,k='post',conversation?:string){let blob:Blob=f;if(f.type.startsWith('image/')){if(!['image/jpeg','image/png','image/webp'].includes(f.type))throw Error('Choose a JPG, PNG or WebP photo.');const url=URL.createObjectURL(f);try{const im=await new Promise<HTMLImageElement>((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=()=>reject(Error('Unable to read this photo. Please choose another.'));image.src=url});const c=document.createElement('canvas'),scale=Math.min(1,1600/Math.max(im.naturalWidth,im.naturalHeight));c.width=Math.max(1,Math.round(im.naturalWidth*scale));c.height=Math.max(1,Math.round(im.naturalHeight*scale));const ctx=c.getContext('2d');if(!ctx)throw Error('This device cannot process the photo.');ctx.drawImage(im,0,0,c.width,c.height);let quality=.88;do{const compressed=await new Promise<Blob|null>(resolve=>c.toBlob(resolve,'image/jpeg',quality));if(!compressed)throw Error('Unable to process this photo. Please try another.');blob=compressed;quality-=.12}while(blob.size>=500000&&quality>.12);if(blob.size>=500000)throw Error('Choose a smaller photo. Compression exceeded 500 KB.')}finally{URL.revokeObjectURL(url)}}if(f.type.startsWith('video/')){const d=await duration(f);if(d>(k==='tv'?600:60))throw Error(k==='tv'?'TV episodes must be up to 10 minutes.':k==='chat'?'Chat videos must be up to 1 minute.':'Feed videos must be up to 1 minute.');if(k!=='tv'&&f.size>=5000000){notify('Compressing video. Keep this window open.');blob=await compressVideo(f)}}const form=new FormData();form.append('file',blob,blob.type.startsWith('video/mp4')?'video.mp4':blob.type.startsWith('video/webm')?'video.webm':f.name);form.append('kind',k);if(conversation)form.append('conversation',conversation);const r=await fetch('/api/upload',{method:'POST',body:form}),d:any=await r.json();if(!r.ok)throw Error(d.error);return d}
