async function callSetup(video:boolean){const s=await navigator.mediaDevices.getUserMedia({audio:true,video});stream.current=s;const connection=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});pc.current=connection;s.getTracks().forEach(t=>connection.addTrack(t,s));connection.onicecandidate=e=>{if(e.candidate)signal('ice',e.candidate.toJSON()).catch(()=>{})};connection.ontrack=e=>{if(remote.current)remote.current.srcObject=e.streams[0]};connection.onconnectionstatechange=()=>{if(connection.connectionState==='connected'){setCall({video,status:'Connected'});connected.current=true;if(outgoingCall.current)callBilling.current=api('call-start',{conversation:chat.id}).catch(e=>{notify(e.message);stopCall();return null})}if(connection.connectionState==='failed'){notify('Connection failed. Please try again.');stopCall()}};setCall({video,status:'Connecting…'});setTimeout(()=>{if(local.current)local.current.srcObject=s},100);return connection}
async function callUser(video:boolean){outgoingCall.current=true;callBilling.current=null;await run(async()=>{const c=await callSetup(video),offer=await c.createOffer();await c.setLocalDescription(offer);await signal('offer',{...offer,video})})}async function acceptCall(){outgoingCall.current=false;callBilling.current=null;await run(async()=>{const c=await callSetup(!!incoming.video);await c.setRemoteDescription({type:incoming.type,sdp:incoming.sdp});const a=await c.createAnswer();await c.setLocalDescription(a);await signal('answer',a);setIncoming(null)})}async function endCall(){await run(async()=>{await signal('hangup',{});if(connected.current){await callBilling.current;await api('call-end',{conversation:chat.id});}stopCall();await load()})}
async function record(){if(recording)return;await run(async()=>{const s=await navigator.mediaDevices.getUserMedia({audio:true}),r=new MediaRecorder(s),chunks:Blob[]=[];rec.current=r;recTime.current=Date.now();r.ondataavailable=e=>chunks.push(e.data);r.onstop=()=>{s.getTracks().forEach(t=>t.stop());setRecording(false);const b=new Blob(chunks,{type:r.mimeType});setVoice({blob:b,url:URL.createObjectURL(b),duration:Math.min(1800,Math.max(1,Math.ceil((Date.now()-recTime.current)/1000)))})};r.start();setRecording(true);setTimeout(()=>{if(r.state==='recording')r.stop()},1800000)})}async function sendVoice(){setBusy('Sending…');await run(async()=>{const u=await upload(new File([voice.blob],'voice.webm',{type:voice.blob.type}),'voice');await api('message',{conversation:chat.id,kind:'voice',body:u.url,duration:voice.duration});setVoice(null);await refreshChat();await load()});setBusy('')}
useEffect(()=>{if(!me?.id)return;const refresh=()=>api('balance').then(b=>{setData((d:any)=>({...d,me:{...d.me,balance:b.balance,bonus:b.bonus}}));setWallet((w:any)=>({...w,balance:b.balance,bonus:b.bonus,total:b.total}))}).catch(()=>{});const onVisible=()=>{if(document.visibilityState==='visible')refresh()};const timer=setInterval(refresh,20000);document.addEventListener('visibilitychange',onVisible);return()=>{clearInterval(timer);document.removeEventListener('visibilitychange',onVisible)}},[me?.id]);
function openShop(username:string){setShop(username);setMarketProduct('');setModal('');go('Marketplace')}
function openMarketProduct(id:string){setMarketProduct(id);if(id){setPage('Marketplace')}}
const nav=[['Home',Home],['Marketplace',ShoppingBag],['Investment',WealthIcon],['Discover',Compass],['eConect TV',Radio],['Messages',MessageCircle],['Wallet',Wallet],['Notifications',Bell]]as const;
function searchBar(phone:boolean){return <div className={'search-box '+(phone?'phone-search':'desktop-search')}>{!phone&&<Search size={18}/>}<input placeholder="Search people, posts and inspiration" value={query} autoComplete="off" onFocus={()=>setSuggestionsOpen(true)} onKeyDown={e=>{if(e.key==='Escape')setSuggestionsOpen(false);if(e.key==='Enter'){setSuggestionsOpen(false);go('Home')}}} onChange={e=>{setSuggestions({members:[],posts:[],hashtags:[]});setQuery(e.target.value);setSuggestionsOpen(true);setPage('Home')}}/><button aria-label="Search eConect" onClick={()=>{setSuggestionsOpen(false);go('Home')}}><Search size={16}/></button><SearchSuggestions/></div>}
function SearchSuggestions(){if(!suggestionsOpen||!query.trim()||!(suggestions.members.length||suggestions.posts.length||suggestions.hashtags.length))return null;function showResults(term:string){setQuery(term);setSuggestionsOpen(false);setModal('');setPage('Home')}return <div className="search-suggestions" aria-label="Search suggestions">{suggestions.members.length>0&&<><div className="suggestion-heading">People</div>{suggestions.members.map((p:any)=><button type="button" key={p.id} onClick={()=>{setSuggestionsOpen(false);setQuery('');profile(p)}}>{p.avatar?<img src={p.avatar} alt=""/>:<span className="suggestion-initial">{p.name?.[0]||'e'}</span>}<span><strong>{p.name} {p.surname}</strong><small>@{p.username}</small></span></button>)}</>}{suggestions.posts.length>0&&<><div className="suggestion-heading">Posts</div>{suggestions.posts.map((p:any)=><button type="button" key={p.id} onClick={()=>showResults(p.body.slice(0,80))}><span><strong>{p.body.slice(0,80)}{p.body.length>80?'…':''}</strong><small>Post by {p.name} {p.surname} · @{p.username}</small></span></button>)}</>}{suggestions.hashtags.length>0&&<><div className="suggestion-heading">Hashtags</div>{suggestions.hashtags.map((tag:string)=><button type="button" key={tag} onClick={()=>showResults(tag)}><strong>{tag}</strong></button>)}</>}</div>}
function renderMembers(){return <section className="member-section"><div className="section-title"><div><h3>Find eConect members <i className="dot"/></h3><p>A familiar face. A brand new connection.</p></div><button className="text-button" onClick={()=>go('Discover')}>View all <ArrowRight size={14}/></button></div><div className="member-strip">{members.filter((p:any)=>p.id!==me?.id&&!hidden.includes(p.id)).slice(0,5).map((p:any)=><div className="member-tile" key={p.id}><Avatar p={p} size={62} click={()=>profile(p)} badge={personUnread(p.id)}/><strong>{p.name}</strong><small>@{p.username.split('_')[0]}</small><div className="member-actions"><button className="yes" title="View profile" onClick={()=>profile(p)}><Check size={14}/></button><button className="no" title="Skip member" onClick={()=>setHidden([...hidden,p.id])}><X size={13}/></button></div></div>)}</div></section>}
function renderPost(p:any){p={...p,...postCounts[p.id]};const files=JSON.parse(p.media);return <article key={p.id} className="post card" id={'post-'+p.id}><div className="post-head"><Avatar p={p} click={()=>profile({...p,id:p.user})} badge={personUnread(p.user)}/><div><button className="name-button" onClick={()=>profile({...p,id:p.user})}>{p.name} {p.surname}<ShieldCheck size={13}/></button><small>@{p.username} <span>·</span> {p.created==='Sample'?'Community preview':new Date(p.created+'Z').toLocaleDateString(undefined,{month:'short',day:'numeric'})} <Globe size={11}/></small></div><button className="icon-button more" aria-label="Post options" onClick={()=>{setSelected(p);setModal('post-options')}}><MoreHorizontal size={20}/></button></div><p className="post-body">{p.body}</p>{files.length>0&&<div className={'post-media '+(files.length>1?'multi':'')}>{files.slice(0,4).map((m:any,i:number)=><div className="post-media-tile" key={i}>{m.type==='video'?<PostVideo src={m.url} poster={m.poster} onOpen={()=>{setSelected({items:files,index:i});setModal('image')}}/>:<button aria-label={i===3&&files.length>4?'View '+(files.length-3)+' more photos and videos':'Open media '+(i+1)} onClick={()=>{setSelected({items:files,index:i});setModal('image')}}><img src={m.url} alt="Community photo" loading="lazy"/>{i===3&&files.length>4&&<span className="media-more">+{files.length-4}</span>}</button>}{m.type==='video'&&i===3&&files.length>4&&<button className="video-media-more" onClick={()=>{setSelected({items:files,index:i});setModal('image')}} aria-label="View more media">+{files.length-4}</button>}</div>)}</div>}<div className="post-stats"><span><i className="mini-heart"><Heart size={10} fill="currentColor"/></i>{p.likes||'Be the first to like'}</span><button onClick={()=>openComments(p)}>{p.comments||0} comments</button></div><div className="post-actions"><span className="post-like-control"><button title="Each like: 4 points transferred to the post owner" onClick={()=>like(p)}><Heart size={18} fill={p.liked?'currentColor':'none'}/> Like</button>{me&&p.user===me.id&&<LikeFlight people={likeEvents.filter((e:any)=>e.post===p.id).slice(0,30)}/>}</span><button onClick={()=>openComments(p)}><MessageCircle size={18}/> Comment</button><button onClick={()=>share(p)}><Share2 size={17}/> Share</button></div></article>}
if(initialLoad!=='ready')return <main className="startup-screen" aria-live="polite">{initialLoad==='loading'?null:<><p>Unable to load eConect. Please check your connection.</p><button className="primary" onClick={()=>{setInitialLoad('loading');load().then(ok=>setInitialLoad(ok?'ready':'error'))}}>Try again</button></>}</main>;
