{modal==='login'&&<div className="auth-modal"><span className="brand-mark big">e</span><div className="eyebrow">YOUR PEOPLE ARE HERE</div><h2>A world of connection.<br/>A place for you.</h2><p>Log in with your eConect account to share, connect, and start conversations.</p><form onSubmit={e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));setBusy('Logging in…');run(async()=>{await api('auth/login',b);setGuest(false);const d=await api('bootstrap');setData(d);setModal(d.me?'':'signup')}).finally(()=>setBusy(''))}}><label>Email<input name="email" type="email" autoComplete="email" required/></label><label>Password<PasswordInput name="password" autoComplete="current-password" required/></label><button className="primary full" disabled={!!busy}>{busy||'Log in'}<ArrowRight size={17}/></button></form><button className="text-button" onClick={()=>setModal('forgot')}>Forgot password?</button><button className="secondary full" onClick={()=>setModal('signup')}>Create an eConect account</button><small>Be kind. Be yourself. Make a connection.</small></div>}
